import{R as e,e as o,f as r,U as s}from"./chunks/framework.ywem4qy5.js";const d=JSON.parse('{"title":"Get Form Support","description":"","frontmatter":{},"headers":[],"relativePath":"get-started/get-form-support.md","filePath":"get-started/get-form-support.md","lastUpdated":1775908585000}'),i={name:"get-started/get-form-support.md"};function a(n,t,p,l,u,c){return o(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="get-form-support" tabindex="-1">Get Form Support <a class="header-anchor" href="#get-form-support" aria-label="Permalink to &quot;Get Form Support&quot;">​</a></h1><p>We offer several support methods when it comes to getting help with Formie. However, you can use the in-built support form to send us a bunch of detail about your form, including fields and settings. This greatly improves changes of the support team replicating your issue if we have your same setup.</p><p>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Get Support</strong> and follow the instructions to fill out a support request.</p><p>We only collect the information that we require to troubleshoot a forms issue:</p><ul><li>Your Craft version</li><li>Your Formie version and license</li><li>Your Formie log file(s)</li><li>Your <code>composer.json</code> and <code>composer.lock</code> files</li><li>Your form (selected below) settings, fields, and notifications</li><li>Your custom form/email templates (if using any)</li></ul><p>Any other content such as your content in entries, user data, orders, products, etc. is not sent to support.</p>',6)])])}const f=e(i,[["render",a]]);export{d as __pageData,f as default};
